Dataspatium.assets.register("presets/api/scb-geodata.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"scb-geodata\",\n  \"name\": \"SCB öppna geodata (WFS)\",\n  \"publisher\": \"Statistiska centralbyrån\",\n  \"description\": \"Statistikområden och gränser från SCB som geodata: DeSO, RegSO, tätorter, kommuner och län med flera. Välj lager i lagerlistan och hämta objekten med geometri.\",\n  \"docs\": \"https://www.scb.se/vara-tjanster/oppna-data/oppna-geodata/\",\n  \"license\": {\n    \"name\": \"CC0 1.0\",\n    \"url\": \"https://creativecommons.org/publicdomain/zero/1.0/\"\n  },\n  \"level\": 1,\n  \"country\": \"SE\",\n  \"baseUrl\": \"https://geodata.scb.se/geoserver/wfs\",\n  \"auth\": {\n    \"type\": \"none\"\n  },\n  \"family\": {\n    \"type\": \"geodata\",\n    \"kind\": \"wfs\"\n  },\n  \"endpoints\": [],\n  \"notes\": \"Lagren hämtas från tjänsten när källan öppnas (GetCapabilities respektive tjänstekatalogen). Svaren är GeoJSON i WGS 84 och öppnas som kartor.\",\n  \"i18n\": {\n    \"en\": {\n      \"name\": \"SCB open geodata (WFS)\",\n      \"description\": \"Statistical areas and boundaries from Statistics Sweden as geodata: DeSO, RegSO, urban areas, municipalities and counties. Choose a layer in the layer list and fetch the features with geometry.\",\n      \"notes\": \"The layers are read from the service when the source is opened (GetCapabilities or the service directory). Answers are GeoJSON in WGS 84 and open as maps.\"\n    },\n    \"da\": {\n      \"name\": \"SCB åbne geodata (WFS)\",\n      \"description\": \"Statistiske områder og grænser fra SCB som geodata: DeSO, RegSO, byområder, kommuner og län med flere. Vælg et lag i laglisten og hent objekterne med geometri.\",\n      \"notes\": \"Lagene hentes fra tjenesten, når kilden åbnes (GetCapabilities henholdsvis tjenestekataloget). Svarene er GeoJSON i WGS 84 og åbnes som kort.\"\n    },\n    \"nb\": {\n      \"name\": \"SCB åpne geodata (WFS)\",\n      \"description\": \"Statistiske områder og grenser fra SCB som geodata: DeSO, RegSO, tettsteder, kommuner og län med flere. Velg et lag i laglisten og hent objektene med geometri.\",\n      \"notes\": \"Lagene hentes fra tjenesten når kilden åpnes (GetCapabilities respektive tjenestekatalogen). Svarene er GeoJSON i WGS 84 og åpnes som kart.\"\n    },\n    \"fi\": {\n      \"name\": \"SCB:n avoin paikkatieto (WFS)\",\n      \"description\": \"Tilastoalueet ja rajat SCB:ltä paikkatietona: DeSO, RegSO, taajamat, kunnat ja läänit ja muita. Valitse taso tasoluettelosta ja nouda kohteet geometrioineen.\",\n      \"notes\": \"Tasot noudetaan palvelusta, kun lähde avataan (GetCapabilities tai palveluhakemisto). Vastaukset ovat GeoJSONia WGS 84:ssä ja avautuvat karttoina.\"\n    },\n    \"is\": {\n      \"name\": \"Opin landupplýsingagögn SCB (WFS)\",\n      \"description\": \"Hagskýrslusvæði og mörk frá SCB sem landupplýsingar: DeSO, RegSO, þéttbýli, sveitarfélög og lén og fleira. Veldu lag í lagalistanum og sæktu fitjurnar með rúmfræði.\",\n      \"notes\": \"Lögin eru sótt úr þjónustunni þegar uppsprettan er opnuð (GetCapabilities eða þjónustuskráin). Svörin eru GeoJSON í WGS 84 og opnast sem kort.\"\n    }\n  }\n}\n");
